"""Visible receiver alignment; source-space endpoints are reviewed image observations."""
import base64,hashlib,json,math
from pathlib import Path
P=Path(__file__).resolve().parent;ROOT=P.parents[2]
def bind(p):return dict(path=str(p.relative_to(ROOT)),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
old=json.loads((P.parent/'body-outfit-v35/slot-contract.json').read_text());body=ROOT/old['body']['file']['path'];head=P/'head-skin-raw.png'
def apply(m,p):return[m[0]*p[0]+m[2]*p[1]+m[4],m[1]*p[0]+m[3]*p[1]+m[5]]
body_points=[[388,250],[485,220]];head_points=[[609,1119],[846,1061]];targets=[apply(old['body']['matrix'],p) for p in body_points]
angle=lambda a,b:math.atan2(b[1]-a[1],b[0]-a[0]);turn=angle(*targets)-angle(*head_points);s=.11;c=math.cos(turn)*s;sn=math.sin(turn)*s;a=[sum(p[k] for p in head_points)/2 for k in [0,1]];b=[sum(p[k] for p in targets)/2 for k in [0,1]];m=[c,sn,-sn,c,b[0]-c*a[0]+sn*a[1],b[1]-sn*a[0]-c*a[1]]
data=dict(canvas=[512,512],body=bind(body),head=bind(head),body_matrix=old['body']['matrix'],head_matrix=m,body_receiver_points_native=body_points,head_insertion_points_native=head_points,target_receiver_points=targets,head_size_scale=s,head_scale_note='New raw head resolution: scale .11 preserves prior reviewed reduced silhouette size, not comparable directly to old .40.',fixed_rest_angle_radians=turn,draw_order=['body_outfit','head','body_collar_foreground'],collar_foreground_polygon_native=[[383,254],[491,216],[509,265],[391,308]],collar_owner='body_outfit_only',observation_method='Manually reviewed visible painted collar/neck edges, not automatic hidden anatomy.',endpoint_budget_px=2,source_uncertainty_px=dict(body=3,head=6),prior_bad_case=bind(P.parent/'body-outfit-v35/preview/original.png'),user_new_art_approved=False)
(P/'neck-bind.json').write_text(json.dumps(data,indent=2)+'\n')
images={n:'data:image/png;base64,'+base64.b64encode((ROOT/data[n]['path']).read_bytes()).decode() for n in ['body','head']}
html='''<!doctype html><meta charset="utf-8"><style>body{background:#1d2935;color:#eef;font:16px system-ui}canvas{background:#344351}</style><h1>Actual neck receiver alignment</h1><canvas id="view" width="512" height="512"></canvas><script>const D=__DATA__,SRC=__IMAGES__,images={},ctx=document.getElementById('view').getContext('2d');let ready=false;Promise.all(Object.entries(SRC).map(([n,src])=>new Promise(resolve=>{const im=new Image;im.onload=()=>{images[n]=im;resolve()};im.src=src}))).then(()=>{ready=true;draw()});function draw(mode='both'){ctx.setTransform(1,0,0,1,0,0);ctx.clearRect(0,0,512,512);for(const n of ['body','head'])if(mode==='both'||mode===n){ctx.setTransform(...D[n+'_matrix']);ctx.drawImage(images[n],0,0)}if(mode==='both'){ctx.save();ctx.setTransform(...D.body_matrix);ctx.beginPath();D.collar_foreground_polygon_native.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.clip();ctx.drawImage(images.body,0,0);ctx.restore()}ctx.setTransform(1,0,0,1,0,0)}window.neck={get ready(){return ready},data:D,frame(mode='both'){draw(mode);return ctx.canvas.toDataURL('image/png')}};</script>'''
html=html.replace('images[n]=im;resolve()', '''const c=document.createElement('canvas');c.width=im.width;c.height=im.height;const x=c.getContext('2d');x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height);for(let k=3;k<d.data.length;k+=4)if(d.data[k]>=240)d.data[k]=255;x.putImageData(d,0,0);images[n]=c;resolve()''')
html=html.replace("if(mode==='both'){ctx.save()", "if(mode==='both'||mode==='collar'){ctx.save()")
(P/'neck-preview.html').write_text(html.replace('__DATA__',json.dumps(data)).replace('__IMAGES__',json.dumps(images)))
